{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [session("a", 1, True), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([session("a", 1, None)]) == 0.0


def test_conversion_rate_empty():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session(str(i), 1, False) for i in range(3)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    result = pooled_conversion_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_and_field_whitespace():
    assert parse_session_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"]) == [
        session("a", 1, True), session("b", -2, False), session("c", 3, None),
    ]


def test_parse_session_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", "  \t# not,a,session", "a,1,1", "\n", "b,2,0"]
    assert parse_session_log(iter(lines)) == [session("a", 1, True), session("b", 2, False)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", "  # comment", "valid,1,1", " \t", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    first = session("a", 10, True)
    last = session("a", 2, None)
    b = session("b", 2, True)
    c = session("c", 1, False)
    events = [first, b, c, session("a", 20, False), last]
    assert dedupe_sessions(events) == [c, last, b]
    assert events == [first, b, c, session("a", 20, False), last]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_zero_filled_and_range_limited():
    events = [
        session("before", 0, True), session("a", 1, True),
        session("b", 1, True), session("c", 2, False),
        session("d", 2, None), session("e", 4, True),
        session("after", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


def test_campaign_summary_uses_calendar_days_and_pooled_rate():
    groups = {
        "a": [session("a", 1, True)],
        "b": [session("b", 3, False), session("c", 5, None)],
        "empty": [],
    }
    assert campaign_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 5)["recent"] == 1
    assert campaign_summary(groups, 20)["recent"] == 1
    assert campaign_summary(groups, 0)["recent"] == 0


def test_campaign_summary_counts_recent_conversions_across_groups():
    groups = {
        "a": [session("a", 1, True), session("b", 4, True)],
        "b": [session("c", 4, True), session("d", 3, True)],
    }
    assert campaign_summary(groups, 2) == {"rate": 1.0, "recent": 3, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]),
                                         (10, ["best", "a", "z", "worst"])])
def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [session("z1", 1, True), session("z2", 1, False)],
        "empty": [],
        "worst": [session("w", 1, False)],
        "a": [session("a1", 1, True), session("a2", 1, None)],
        "best": [session("b", 1, True)],
    }
    assert top_converting_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_converting_groups_no_sessions(groups):
    assert top_converting_groups(groups, 2) == []


def test_conversion_rate_by_group_sorted_keys_and_empty_groups():
    groups = {
        "z": [session("a", 1, True), session("b", 1, None)],
        "m": [session("c", 1, False)],
        "a": [],
    }
    result = conversion_rate_by_group(groups)
    assert result == {"a": None, "m": 0.0, "z": 0.5}
    assert list(result) == ["a", "m", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3, 4, 5], 3),
     ([1, 0, 1, 0, 1], 1), ([1, -1, 2], 1), ([1, 2, 3], 3),
     ([1, 2, 0, 1], 2)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
